    }
    public string group_bake_sample(RefCounted owner,Control editor,Settings job,int index)
    {
        if(!group_bake_valid(editor,job))return "Scene closed; nothing was saved.";if(owner.Get("bake_cancelled").AsBool())return "Bake canceled; the previous bake was preserved.";string signature=owner.Get("signature").AsString();if(job["expected"].AsString().Length==0)job["expected"]=signature;if(signature!=job["expected"].AsString())return "Scene changed during bake; nothing was saved.";var frame=snapshot(Map(owner,"base_display_states"));frame["@inputs"]=GD.Load<GDScript>("res://scripts/actors/physics/destruction/bake_editing.gd").Call("prefix_signature",job["model"],job["at"]);frame["@scene_time"]=job["at"];var model=job["model"].As<RefCounted>();foreach(var value in job["actors"].AsGodotArray()){var actor=value.As<Resource>();if(model.Call("actor_for_id",actor.Get("id")).AsGodotObject()!=actor||!frame.ContainsKey(actor.Get("id")))return "A simulation actor was removed; nothing was saved.";}string error=job["cache"].As<Resource>().Call("append",frame).AsString();if(error.Length==0)owner.Set("bake_progress",(double)(index+1)/job["count"].AsInt32());return error;
    }
