            string finalSignature;try{for(int i=0;i<actors.Count;i++)Values(actors[i].As<Resource>())[new StringName("physics")]=planned[i];finalSignature=_settings.fingerprint(model);}finally{for(int i=0;i<actors.Count;i++)Values(actors[i].As<Resource>())[new StringName("physics")]=before[i];}var history=model.Get("history").As<UndoRedo>();history.CreateAction("Bake interacting physics group");for(int i=0;i<actors.Count;i++){var after=planned[i].AsGodotDictionary();after["bake"].AsGodotDictionary()["signature"]=finalSignature;BakeHistory(model,actors[i].As<Resource>(),before[i].AsGodotDictionary(),after);}history.CommitAction();}
        Map(owner,"_baking_actors").Clear();owner.Set("signature","");mark_dirty(owner);if(error.Length>0)cache.Call("abort_stream");if(group_bake_valid(editor,job)){editor.Get("canvas").AsGodotObject().Set("playhead",job["saved_time"]);editor.Set("playing",job["saved_playing"]);editor.Call("_evaluate_runtimes");}return error;
